import { unstable_after as after } from 'next/server';

export interface PageViewData {
  pathname: string;
  timestamp: Date;
  userAgent?: string;
  referrer?: string;
}

export class AnalyticsService {
  private static instance: AnalyticsService;

  private constructor() {}

  static getInstance(): AnalyticsService {
    if (!AnalyticsService.instance) {
      AnalyticsService.instance = new AnalyticsService();
    }
    return AnalyticsService.instance;
  }

  async logPageView(data: PageViewData): Promise<void> {
    after(async () => {
      try {
        await this.sendToAnalyticsService(data);
      } catch (error) {
        console.error('Failed to log page view:', error);
      }
    });
  }

  private async sendToAnalyticsService(data: PageViewData): Promise<void> {
    const payload = {
      event: 'page_view',
      data: {
        ...data,
        timestamp: data.timestamp.toISOString()
      }
    };

    console.log('Analytics event scheduled:', payload);

    await new Promise(resolve => setTimeout(resolve, 0));

    console.log('Page view logged:', {
      path: data.pathname,
      time: data.timestamp.toISOString()
    });
  }

  async logCustomEvent(eventName: string, eventData: Record<string, any>): Promise<void> {
    after(async () => {
      try {
        console.log('Custom event logged:', { eventName, eventData });
      } catch (error) {
        console.error('Failed to log custom event:', error);
      }
    });
  }
}

