import { AnalyticsService, PageViewData } from '@/lib/analytics';
import { headers } from 'next/headers';

interface WelcomeWithAnalyticsProps {
  userName?: string;
  showDetails?: boolean;
}

export default async function WelcomeWithAnalytics({
  userName = 'Guest',
  showDetails = true
}: WelcomeWithAnalyticsProps) {
  const headersList = await headers();
  const analyticsService = AnalyticsService.getInstance();

  const pageViewData: PageViewData = {
    pathname: '/',
    timestamp: new Date(),
    userAgent: headersList.get('user-agent') || undefined,
    referrer: headersList.get('referer') || undefined
  };

  await analyticsService.logPageView(pageViewData);

  return (
    <div className="welcome-container">
      <h1 className="welcome-title">Welcome, {userName}!</h1>
      <p className="welcome-message">
        Thank you for visiting our application. We're glad to have you here.
      </p>

      {showDetails && (
        <div className="welcome-details">
          <p>Your visit has been logged for analytics purposes.</p>
          <p>The analytics logging happens after the page is sent to your browser, so it doesn't delay your experience.</p>
        </div>
      )}

      <div className="welcome-features">
        <h2>Features:</h2>
        <ul>
          <li>Server-side rendering</li>
          <li>Non-blocking analytics</li>
          <li>Real-time logging</li>
          <li>Performance optimized</li>
        </ul>
      </div>

      <style jsx>{`
        .welcome-container {
          max-width: 800px;
          margin: 0 auto;
          padding: 2rem;
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          border-radius: 12px;
          color: white;
          box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
        }

        .welcome-title {
          font-size: 2.5rem;
          margin-bottom: 1rem;
          text-align: center;
        }

        .welcome-message {
          font-size: 1.2rem;
          line-height: 1.6;
          margin-bottom: 1.5rem;
          text-align: center;
        }

        .welcome-details {
          background: rgba(255, 255, 255, 0.1);
          padding: 1.5rem;
          border-radius: 8px;
          margin-bottom: 2rem;
          border-left: 4px solid #4ade80;
        }

        .welcome-details p {
          margin: 0.5rem 0;
        }

        .welcome-features {
          background: rgba(255, 255, 255, 0.1);
          padding: 1.5rem;
          border-radius: 8px;
        }

        .welcome-features h2 {
          margin-top: 0;
          margin-bottom: 1rem;
        }

        .welcome-features ul {
          list-style-type: none;
          padding: 0;
          margin: 0;
        }

        .welcome-features li {
          padding: 0.5rem 0;
          border-bottom: 1px solid rgba(255, 255, 255, 0.2);
        }

        .welcome-features li:last-child {
          border-bottom: none;
        }

        @media (max-width: 768px) {
          .welcome-container {
            padding: 1.5rem;
            margin: 1rem;
          }

          .welcome-title {
            font-size: 2rem;
          }
        }
      `}</style>
    </div>
  );
}

