// Simple test to verify analytics service works
import { AnalyticsService } from './lib/analytics.js';

async function testAnalytics() {
  console.log('Testing analytics service...');

  const analytics = AnalyticsService.getInstance();

  const testData = {
    pathname: '/test',
    timestamp: new Date(),
    userAgent: 'Test Agent',
    referrer: 'https://example.com'
  };

  console.log('Logging page view...');
  await analytics.logPageView(testData);

  console.log('Logging custom event...');
  await analytics.logCustomEvent('test_event', { test: true, value: 123 });

  console.log('Test completed. Analytics events have been scheduled.');
  console.log('Note: Actual logging happens after response is sent (using after/setTimeout).');
}

testAnalytics().catch(console.error);
